<script setup>
import { ref } from 'vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MUpload from '../../../components/mds/MUpload.vue'; import { awardFileUrl } from '../domain/award-view.mjs';
const props = defineProps({ files: { type: Array, default: () => [] }, canUpload: Boolean, uploading: Boolean, error: String }); const emit = defineEmits(['upload']); const localError = ref(''); function select(files) { localError.value = ''; emit('upload', files); } function oversized(files) { localError.value = `${files.length} tệp vượt quá 5MB nên chưa được tải lên.`; }
</script>
<template><section class="rounded-lg bg-[var(--mds-bg)] p-5 shadow-[var(--mds-shadow-card)]"><h2 class="text-[16px] font-semibold">Tài liệu đính kèm</h2><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Tên tệp là metadata được phép xem; máy chủ kiểm tra lại quyền trước khi mở nội dung.</p><div v-if="files.length" class="mt-4 divide-y divide-[var(--mds-border-light)]"><div v-for="file in files" :key="file.id" class="flex min-h-[52px] items-center justify-between gap-3 py-2"><span class="min-w-0"><strong class="block truncate text-[13px]">{{ file.name }}</strong><span class="text-[12px] text-[var(--mds-text-secondary)]">{{ file.kind }} · {{ file.mime }}</span></span><a :href="awardFileUrl(file.id)" target="_blank" rel="noopener" class="text-[13px] font-medium text-[var(--mds-brand-700)] hover:underline">Mở tệp</a></div></div><MEmptyState v-else class="mt-4" title="Chưa có tài liệu" description="Tài liệu được phép xem sẽ xuất hiện tại đây."/><div v-if="canUpload" class="mt-4 rounded-lg bg-[var(--mds-bg-page)] p-3"><MUpload label="Tải tài liệu giải thưởng" accept="application/pdf,image/jpeg,image/png,image/webp,.doc,.docx,.xls,.xlsx,.ppt,.pptx" :disabled="uploading" @select-files="select" @oversized="oversized"/></div><p v-if="localError || error" role="alert" class="mt-3 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ localError || error }}</p></section></template>
